            <stop offset="0" stop-color="#CC0099"/><stop offset="1" stop-color="#FF69B4"/></linearGradient></defs>
          <g stroke="url(#gA)" stroke-width="7" stroke-linecap="round">
            <line x1="13" y1="13" x2="51" y2="51"/><line x1="51" y1="13" x2="13" y2="51"/></g>
          <circle cx="32" cy="32" r="5.5" fill="#FF69B4"/>
        </svg>
        <span class="mono" style="color:var(--fg-3);">min 16px</span>
      </div>
      <div class="demo" style="padding:24px;">
