        <div style="display:flex; align-items:center; gap:12px;">
          <svg width="34" height="34" viewBox="0 0 64 64" aria-hidden="true">
            <g stroke="url(#gA)" stroke-width="7" stroke-linecap="round">
              <line x1="13" y1="13" x2="51" y2="51"/><line x1="51" y1="13" x2="13" y2="51"/></g>
            <circle cx="32" cy="32" r="5.5" fill="#FF69B4"/>
          </svg>
          <span style="font-size:24px; font-weight:600; letter-spacing:-.01em;">codx<span style="color:var(--primary-fg)">-</span>junior</span>
        </div>
      </div>
      <div class="demo" style="padding:24px; display:grid; place-items:center; gap:8px;">
        <div class="demo-label" style="margin:0;">Stacked · min 64px</div>
        <svg width="30" height="30" viewBox="0 0 64 64" aria-hidden="true">
          <g stroke="url(#gA)" stroke-width="7" stroke-linecap="round">
