        <svg width="28" height="28" viewBox="0 0 64 64" aria-hidden="true"><g stroke="#fff" stroke-width="7" stroke-linecap="round"><line x1="13" y1="13" x2="51" y2="51"/><line x1="51" y1="13" x2="13" y2="51"/></g><circle cx="32" cy="32" r="5.5" fill="#fff"/></svg>
