  <!-- ══ Typography ══════════════════════════════════════════════════════ -->
  <section id="type">
    <div class="sec-head"><span class="num">05</span><h2>Typography</h2></div>
    <p class="sub">Two voices. The interface speaks in a neutral system sans, the machine speaks in
      monospace. <strong>Test:</strong> if a user could paste the string into a terminal and it would mean
      something, it is monospace. That single rule makes the product read technical and calm.</p>

    <div class="grid g2" style="margin-bottom:20px;">
      <div class="demo">
        <div class="demo-label">Interface voice</div>
        <div style="font-size:16px; line-height:26px;">Save changes · Task Manager · Running tests… 3 of 12</div>
        <div class="mono" style="font-size:11px; color:var(--fg-3); margin-top:8px;">system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif</div>
      </div>
      <div class="demo">
        <div class="demo-label">Machine voice</div>
        <div class="mono" style="font-size:16px; line-height:26px;">claude-sonnet-4-5 · api/chat/chat.py · 12.4k</div>
        <div class="mono" style="font-size:11px; color:var(--fg-3); margin-top:8px;">ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace</div>
      </div>
    </div>

    <div class="card" style="margin-bottom:20px;">
      <div class="demo-label">Scale — eight steps</div>
      <div class="spec"><div class="t">display · 36/40 · 600</div><div class="t-display">Build faster, together</div></div>
      <div class="spec"><div class="t">h1 · 24/32 · 600</div><div class="t-h1">Task Manager</div></div>
      <div class="spec"><div class="t">h2 · 20/28 · 600</div><div class="t-h2">Sprint 12 · 14 tasks</div></div>
      <div class="spec"><div class="t">h3 · 16/24 · 600</div><div class="t-h3">Assignees</div></div>
      <div class="spec"><div class="t">body · 14/20 · 400</div><div class="t-body">Default UI text: table cells, buttons, sidebar labels, dense surfaces.</div></div>
      <div class="spec"><div class="t">body-lg · 16/26 · 400</div><div class="t-body-lg">Reading surfaces: chat prose, docs, settings descriptions.</div></div>
      <div class="spec"><div class="t">label · 12/16 · 500</div><div class="t-label">FORM LABEL · metadata · badges</div></div>
      <div class="spec"><div class="t">mono · 13/20</div><div class="t-mono">const tokens = read('design-tokens.json')</div></div>
      <div class="spec"><div class="t">code · 14/20</div><div class="t-code">diff --git a/client/src/main.ts b/client/src/main.ts</div></div>
    </div>

    <div class="grid g2">
      <div class="card">
        <div class="demo-label">Weight &amp; numbers</div>
        <p style="font-size:13px; color:var(--fg-2); margin-bottom:8px;">400 body · 500 labels and interactive text · 600 headings.
          <strong>Never 700+</strong> (system UI turns shouty), <strong>never 300</strong> on dark.</p>
        <table style="margin:0;">
          <tbody>
            <tr><td class="num">12,482</td><td class="num">$0.42</td><td class="num">3m 12s</td><td class="num">1.2 GB</td></tr>
          </tbody>
        </table>
        <div class="mono" style="font-size:11px; color:var(--fg-3); margin-top:6px;">font-variant-numeric: tabular-nums — any column of numbers, always</div>
      </div>
      <div class="card">
        <div class="demo-label">Measures</div>
        <table style="margin:0;">
          <tbody>
            <tr><td>Chat message</td><td>62–78 ch (<code>max-width 800px</code>)</td></tr>
            <tr><td>Docs / wiki</td><td><code>max-width: 68ch</code></td></tr>
            <tr><td>Tables &amp; logs</td><td>no limit — horizontal scroll, never wrap a hash</td></tr>
            <tr><td>Form group</td><td><code>max-width: 480px</code></td></tr>
            <tr><td>Modal body</td><td><code>max-width: 672px</code></td></tr>
          </tbody>
        </table>
      </div>
    </div>

    <h3 style="margin:24px 0 8px;">Code typography</h3>
    <div class="codeblock">
      <div class="bar"><span class="file">client/src/assets/main.css — target</span>
        <button class="copybtn" data-copy=".view-code pre, .view-code code.hljs {
  font-family: var(--font-mono);
  font-size: 14px;          /* 16px is too large for side-by-side diffs */
