        <span style="width:12px"></span>
        <button class="btn btn-secondary btn-sm">sm</button>
        <button class="btn btn-primary btn-sm">Run tests</button>
        <button class="btn btn-primary btn-lg">lg</button>
      </div>
    </div>
    <div class="state-grid" style="margin-bottom:8px;">
      <div class="state-cell"><span class="nm">default</span><button class="btn btn-primary">New chat</button></div>
      <div class="state-cell"><span class="nm">hover · +5% light, 150ms</span><button class="btn btn-primary is-hover">New chat</button></div>
