<meta name="description" content="The codx-junior corporate design playbook: brand, logo, colour, typography, foundations, components, voice, IA, accessibility and governance — with live specimens.">
<style>
/* ═══════════════════════════════════════════════════════════════════════════
   codx-junior design playbook — self-contained, no external requests.
   All values come from design/tokens/design-tokens.json.
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── 1. Tokens ─────────────────────────────────────────────────────────────── */
:root {
  --brand-50:#FFF0FA;  --brand-100:#FFD6F0; --brand-200:#FFAEE0; --brand-300:#FF80CE;
  --brand-400:#FF69B4; --brand-500:#F530A8; --brand-600:#CC0099; --brand-700:#A3007A;
  --brand-800:#7A005B; --brand-900:#4D0039;
  --purple-400:#C24AC2; --purple-500:#B000B0; --purple-600:#8F008F; --purple-700:#6B006B;

  --radius-field:.375rem; --radius-box:.5rem; --radius-selector:.75rem; --radius-full:9999px;
  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  --measure: 74ch;
}

/* Dark = the product default theme */
html[data-theme="dark"] {
  --bg:#1F2937; --raised:#273244; --overlay:#2F3A4D; --sunken:#161E29;
  --border-subtle:rgba(243,244,246,.07); --border:rgba(243,244,246,.13); --border-strong:rgba(243,244,246,.24);
  --fg:#F3F4F6; --fg-2:rgba(243,244,246,.72); --fg-3:rgba(243,244,246,.52); --fg-4:rgba(243,244,246,.38);
  --primary:oklch(65% .32 320); --primary-fill:#CC0099; --primary-fg:#FF69B4;
  --info:oklch(75% .22 220); --success:oklch(68% .28 140); --warning:oklch(82% .26 70); --error:oklch(68% .32 25);
  --shadow-overlay:0 10px 15px -3px rgba(0,0,0,.45);
  --shadow-modal:0 25px 50px -12px rgba(0,0,0,.6);
  --on-brand:#FFFFFF;
  color-scheme: dark;
}
/* Light = the second, supported theme */
html[data-theme="light"] {
  --bg:#FFFFFF; --raised:#FAFAFC; --overlay:#F0F0F5; --sunken:#F3F4F6;
  --border-subtle:#EEEEF2; --border:#E2E2EA; --border-strong:#C9C9D4;
  --fg:#14141E; --fg-2:#3F3F52; --fg-3:#6B7280; --fg-4:#9CA3AF;
  --primary:#CC0099; --primary-fill:#CC0099; --primary-fg:#CC0099;
  --info:#4696DC; --success:#3CB450; --warning:#FFB428; --error:#F05050;
  --shadow-overlay:0 10px 15px -3px rgba(15,18,28,.12);
  --shadow-modal:0 25px 50px -12px rgba(15,18,28,.22);
  --on-brand:#FFFFFF;
  color-scheme: light;
}

/* ── 2. Base ───────────────────────────────────────────────────────────────── */
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 84px; }
body {
  margin: 0; background: var(--bg); color: var(--fg);
  font-family: var(--font-sans); font-size: 14px; line-height: 1.55;
