  display: grid; place-items: center; font-family: var(--font-mono); font-size: 11px; font-weight: 600;
}
.rule b { display: block; font-weight: 600; font-size: 13px; margin-bottom: 2px; }
.rule span { color: var(--fg-2); font-size: 13px; }

/* ── 8. Tables ─────────────────────────────────────────────────────────────── */
table { width: 100%; border-collapse: collapse; font-size: 13px; margin: 0 0 16px; }
th {
  text-align: left; font-size: 12px; font-weight: 500; color: var(--fg-3);
  padding: 8px 12px; border-bottom: 1px solid var(--border); background: var(--raised);
  position: sticky; top: 56px; z-index: 10;
}
td { padding: 8px 12px; border-bottom: 1px solid var(--border-subtle); color: var(--fg-2); vertical-align: top; }
td:first-child { color: var(--fg); }
tr:hover td { background: color-mix(in oklab, var(--fg) 3%, transparent); }
.num-cell { font-variant-numeric: tabular-nums; text-align: right; }
.tbl-wrap { border: 1px solid var(--border-subtle); border-radius: var(--radius-box); overflow: hidden; margin-bottom: 16px; }
.tbl-wrap table { margin: 0; }
.tbl-wrap th { top: 0; background: var(--overlay); }

/* ── 9. Swatches ───────────────────────────────────────────────────────────── */
.ramp { display: grid; grid-template-columns: repeat(10, minmax(0,1fr)); gap: 6px; margin-bottom: 8px; }
.ramp.p2 { grid-template-columns: repeat(4, minmax(0,1fr)); }
.swatch {
  position: relative; height: 76px; border-radius: var(--radius-field); cursor: pointer;
  border: 1px solid var(--border-subtle); padding: 8px;
  display: flex; flex-direction: column; justify-content: flex-end; gap: 1px;
  font-family: var(--font-mono); font-size: 10px; line-height: 1.3;
  transition: transform 150ms ease;
}
.swatch:hover { transform: translateY(-2px); }
.swatch:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }
.swatch .step { font-weight: 700; }
.swatch.light-txt { color: #fff; }
.swatch.dark-txt { color: #111827; }
.swatch::after {
  content: "copied"; position: absolute; inset-inline: 6px; top: 6px;
  background: rgba(0,0,0,.72); color: #fff; font-size: 10px; text-align: center;
  border-radius: 4px; padding: 1px 0; opacity: 0; transition: opacity 150ms ease; pointer-events: none;
}
.swatch.copied::after { opacity: 1; }
.ramp-note { font-size: 12px; color: var(--fg-3); margin: 0 0 20px; }

/* ── 10. Type specimens ────────────────────────────────────────────────────── */
.spec { display: grid; grid-template-columns: 108px minmax(0,1fr); gap: 16px; align-items: baseline; padding: 10px 0; border-bottom: 1px solid var(--border-subtle); }
.spec:last-child { border-bottom: 0; }
.spec .t { font-family: var(--font-mono); font-size: 11px; color: var(--fg-4); }
.t-display { font-size: 36px; line-height: 40px; font-weight: 600; letter-spacing: -.02em; }
.t-h1 { font-size: 24px; line-height: 32px; font-weight: 600; letter-spacing: -.01em; }
.t-h2 { font-size: 20px; line-height: 28px; font-weight: 600; letter-spacing: -.01em; }
.t-h3 { font-size: 16px; line-height: 24px; font-weight: 600; letter-spacing: 0; }
.t-body { font-size: 14px; line-height: 20px; font-weight: 400; }
.t-body-lg { font-size: 16px; line-height: 26px; font-weight: 400; }
.t-label { font-size: 12px; line-height: 16px; font-weight: 500; letter-spacing: .01em; }
.t-mono { font-family: var(--font-mono); font-size: 13px; line-height: 20px; }
.t-code { font-family: var(--font-mono); font-size: 14px; line-height: 20px; font-variant-ligatures: none; tab-size: 2; }
.tabnums { font-variant-numeric: tabular-nums; }

/* ── 11. Code block ────────────────────────────────────────────────────────── */
.codeblock {
  position: relative; background: var(--sunken); border: 1px solid var(--border-subtle);
  border-radius: var(--radius-box); margin: 0 0 16px; overflow: hidden;
}
.codeblock .bar {
  display: flex; align-items: center; gap: 8px; padding: 6px 10px;
  border-bottom: 1px solid var(--border-subtle); background: color-mix(in oklab, var(--fg) 3%, transparent);
}
.codeblock .file { font-family: var(--font-mono); font-size: 11px; color: var(--fg-3); flex: 1; }
.codeblock pre { padding: 12px 14px; overflow-x: auto; font-size: 13px; line-height: 20px; font-variant-ligatures: none; tab-size: 2; color: var(--fg-2); }
.codeblock .c { color: var(--fg-4); }
.codeblock .k { color: var(--primary-fg); }
.codeblock .s { color: var(--success); }
.copybtn {
  font: inherit; font-family: var(--font-mono); font-size: 11px; height: 22px; padding: 0 8px;
  background: color-mix(in oklab, var(--fg) 8%, transparent); color: var(--fg-3);
  border: 1px solid var(--border-subtle); border-radius: var(--radius-field); cursor: pointer;
}
.copybtn:hover { color: var(--fg); }
.copybtn.done { color: var(--success); border-color: color-mix(in oklab, var(--success) 45%, transparent); }

/* ── 12. Do / Don't ────────────────────────────────────────────────────────── */
.pair { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 12px; }
.do, .dont { border-radius: var(--radius-box); padding: 12px 14px; font-size: 13px; border: 1px solid; }
.do { background: color-mix(in oklab, var(--success) 9%, transparent); border-color: color-mix(in oklab, var(--success) 28%, transparent); }
.dont { background: color-mix(in oklab, var(--error) 9%, transparent); border-color: color-mix(in oklab, var(--error) 26%, transparent); }
.do .h, .dont .h { display: flex; align-items: center; gap: 6px; font-weight: 600; font-size: 12px; margin-bottom: 6px; }
.do .h { color: var(--success); }
.dont .h { color: var(--error); }
.do .body, .dont .body { color: var(--fg-2); }

/* ── 13. Component specimens ───────────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  height: 32px; padding: 0 12px; border-radius: var(--radius-field);
  font-family: var(--font-sans); font-size: 14px; font-weight: 500; line-height: 1;
  border: 1px solid transparent; cursor: pointer; transition: background 150ms ease, transform 0ms;
}
.btn:active { transform: scale(.98); }
.btn:focus-visible { outline: 2px solid color-mix(in oklab, var(--primary) 55%, transparent); outline-offset: 2px; }
.btn-primary { background: var(--brand-600); color: #fff; }
.btn-primary:hover { background: color-mix(in oklab, var(--brand-600) 88%, #fff); }
.btn-secondary { background: color-mix(in oklab, var(--fg) 6%, transparent); color: color-mix(in oklab, var(--fg) 82%, transparent); border-color: var(--border); }
.btn-secondary:hover { background: color-mix(in oklab, var(--fg) 10%, transparent); }
.btn-ghost { background: transparent; color: var(--fg-2); }
.btn-ghost:hover { background: color-mix(in oklab, var(--fg) 6%, transparent); }
.btn-danger { background: var(--error); color: #fff; }
.btn-link { background: transparent; color: var(--primary-fg); padding: 0 2px; height: auto; border-bottom: 1px solid color-mix(in oklab, var(--primary-fg) 35%, transparent); border-radius: 0; }
.btn-sm { height: 28px; padding: 0 10px; font-size: 12px; font-weight: 500; }
.btn-lg { height: 40px; padding: 0 16px; font-weight: 600; }

.state-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 10px; }
.state-cell { background: var(--sunken); border: 1px solid var(--border-subtle); border-radius: var(--radius-field); padding: 12px; display: flex; flex-direction: column; gap: 8px; align-items: flex-start; }
.state-cell .nm { font-family: var(--font-mono); font-size: 10px; color: var(--fg-4); text-transform: uppercase; letter-spacing: .06em; }
.is-hover { background: color-mix(in oklab, var(--brand-600) 88%, #fff); }
.is-focus { outline: 2px solid color-mix(in oklab, var(--primary) 55%, transparent); outline-offset: 2px; }
.is-active { transform: scale(.98); background: var(--brand-700); }
.is-disabled { opacity: .5; cursor: not-allowed; }
.spinner {
  width: 14px; height: 14px; border-radius: 50%;
  border: 2px solid color-mix(in oklab, #fff 35%, transparent); border-top-color: #fff;
  animation: spin 700ms linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* inputs */
.field { display: grid; gap: 4px; margin-bottom: 12px; }
.field label { font-size: 12px; font-weight: 500; color: var(--fg-2); }
.field .hint { font-size: 12px; color: var(--fg-3); }
.field .err { font-size: 12px; color: var(--error); display: flex; align-items: center; gap: 5px; }
.input {
  height: 32px; padding: 0 12px; width: 100%; font: inherit; font-size: 14px;
  background: var(--sunken); color: var(--fg); border: 1px solid var(--border);
  border-radius: var(--radius-field);
}
.input::placeholder { color: var(--fg-4); }
.input:focus { outline: 0; border-color: color-mix(in oklab, var(--primary) 60%, transparent); box-shadow: 0 0 0 2px color-mix(in oklab, var(--primary) 20%, transparent); }
.input[aria-invalid="true"] { border-color: var(--error); }
.input:disabled { opacity: .5; cursor: not-allowed; }

/* badges */
.badge { display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px; border-radius: var(--radius-full); font-size: 12px; font-weight: 500; }
.badge.info { background: color-mix(in oklab, var(--info) 18%, transparent); color: var(--info); }
.badge.success { background: color-mix(in oklab, var(--success) 18%, transparent); color: var(--success); }
.badge.warning { background: color-mix(in oklab, var(--warning) 18%, transparent); color: var(--warning); }
.badge.error { background: color-mix(in oklab, var(--error) 18%, transparent); color: var(--error); }
.dot { width: 6px; height: 6px; border-radius: 50%; box-shadow: 0 0 0 1.5px color-mix(in oklab, var(--fg) 10%, transparent); }
.dot.on { background: var(--success); }
.dot.off { background: var(--fg-4); }
.dot.busy { background: var(--warning); }

/* tabs */
.tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--border-subtle); }
.tab { height: 32px; padding: 0 12px; display: inline-flex; align-items: center; font-size: 13px; color: var(--fg-3); background: none; border: 0; border-bottom: 2px solid transparent; cursor: pointer; font-family: inherit; }
.tab:hover { color: var(--fg-2); }
.tab.active { color: var(--fg); border-bottom-color: var(--primary); }
.seg { display: inline-flex; background: color-mix(in oklab, var(--fg) 6%, transparent); border-radius: var(--radius-selector); padding: 2px; gap: 2px; }
.seg button { height: 26px; padding: 0 12px; border: 0; border-radius: var(--radius-field); background: none; color: var(--fg-3); font: inherit; font-size: 12px; font-weight: 500; cursor: pointer; }
.seg button.on { background: var(--raised); color: var(--fg); box-shadow: var(--shadow-overlay); }

/* nav items */
.navlist { display: grid; gap: 2px; }
.navitem { display: flex; align-items: center; gap: 8px; height: 32px; padding: 0 10px; border-radius: var(--radius-selector); font-size: 13px; color: var(--fg-2); }
.navitem:hover { background: color-mix(in oklab, var(--fg) 6%, transparent); }
.navitem.active { background: color-mix(in oklab, var(--primary) 15%, transparent); color: var(--primary-fg); box-shadow: inset 2px 0 0 var(--primary); }
.navitem .count { margin-left: auto; font-family: var(--font-mono); font-size: 11px; color: var(--fg-3); }

/* table specimen */
.dt { width: 100%; border-collapse: collapse; font-size: 13px; }
.dt th { position: static; background: var(--raised); font-size: 12px; font-weight: 500; color: var(--fg-3); }
.dt td { height: 36px; padding: 6px 12px; }
.dt tr.sel td { background: color-mix(in oklab, var(--primary) 10%, transparent); }
.dt .num { font-family: var(--font-mono); font-variant-numeric: tabular-nums; text-align: right; }

/* chat */
.chatrow { display: flex; gap: 12px; margin-bottom: 16px; }
.avatar { flex: 0 0 32px; width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; font-size: 12px; font-weight: 600; }
.avatar.ai { background: var(--brand-600); color: #fff; }
.avatar.me { background: color-mix(in oklab, var(--info) 25%, transparent); color: var(--info); }
.bubble { max-width: 620px; padding: 12px 16px; border-radius: var(--radius-box); font-size: 16px; line-height: 26px; }
.bubble.ai { background: var(--raised); border: 1px solid var(--border-subtle); box-shadow: inset 2px 0 0 color-mix(in oklab, var(--primary) 30%, transparent); }
.bubble.me { background: color-mix(in oklab, var(--primary) 10%, transparent); border: 1px solid color-mix(in oklab, var(--primary) 20%, transparent); }
.meta { display: flex; gap: 8px; flex-wrap: wrap; font-size: 12px; color: var(--fg-3); margin-top: 6px; }
.cursor { display: inline-block; width: 2px; height: 18px; background: var(--primary); vertical-align: -3px; animation: blink 1s steps(2) infinite; }
@keyframes blink { 50% { opacity: 0; } }

/* banner */
.handover {
  display: flex; align-items: flex-start; gap: 12px; padding: 12px 16px;
  background: color-mix(in oklab, var(--warning) 14%, transparent);
  border-top: 1px solid color-mix(in oklab, var(--warning) 30%, transparent);
  border-bottom: 1px solid color-mix(in oklab, var(--warning) 30%, transparent);
  border-radius: var(--radius-box);
}
.handover .ic { color: var(--warning); font-size: 16px; line-height: 1.4; }
.handover b { font-size: 14px; }
.handover p { margin: 2px 0 8px; font-size: 13px; color: var(--fg-2); }

/* board card */
.kcard { position: relative; background: var(--raised); border: 1px solid var(--border-subtle); border-radius: var(--radius-field); padding: 10px 12px 10px 14px; }
.kcard::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; border-radius: 3px 0 0 3px; background: var(--info); }
.kcard.hi::before { background: var(--error); }
.kcard .ttl { font-size: 13px; font-weight: 500; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.kcard .row { display: flex; align-items: center; gap: 6px; margin-top: 8px; font-size: 11px; color: var(--fg-3); }
.avstack { display: flex; }
.avstack .avatar { width: 20px; height: 20px; flex: 0 0 20px; font-size: 9px; border: 2px solid var(--raised); }
.avstack .avatar + .avatar { margin-left: -6px; }

/* modal specimen */
.frame { position: relative; height: 300px; border: 1px dashed var(--border-strong); border-radius: var(--radius-box); overflow: hidden; background: var(--bg); }
.frame .page-mock { padding: 16px; display: grid; gap: 8px; }
.frame .bar-mock { height: 10px; border-radius: 3px; background: color-mix(in oklab, var(--fg) 8%, transparent); }
.modal-layer { position: absolute; inset: 0; display: none; place-items: center; padding: 16px; background: color-mix(in oklab, var(--bg) 60%, transparent); backdrop-filter: blur(4px); }
.modal-layer.open { display: grid; }
.modal-box { width: 100%; max-width: 380px; background: var(--overlay); border: 1px solid var(--border); border-radius: var(--radius-selector); box-shadow: var(--shadow-modal); overflow: hidden; }
.modal-box header { display: flex; align-items: center; padding: 8px 16px; border-bottom: 1px solid var(--border-subtle); font-size: 16px; font-weight: 600; }
.modal-box header .x { margin-left: auto; }
.modal-box .body { padding: 16px; font-size: 14px; color: var(--fg-2); }
.modal-box footer { display: flex; justify-content: flex-end; gap: 12px; padding: 12px 16px; border-top: 1px solid var(--border-subtle); }

/* toast */
.toast { display: flex; align-items: center; gap: 8px; max-width: 320px; padding: 10px 12px; border-radius: var(--radius-box); box-shadow: var(--shadow-overlay); font-size: 14px; }
.toast.success { background: color-mix(in oklab, var(--success) 20%, var(--raised)); color: var(--fg); border: 1px solid color-mix(in oklab, var(--success) 35%, transparent); }
.toast.error { background: color-mix(in oklab, var(--error) 20%, var(--raised)); color: var(--fg); border: 1px solid color-mix(in oklab, var(--error) 35%, transparent); }
.toast .x { margin-left: auto; color: var(--fg-3); cursor: pointer; }

/* empty */
.empty { text-align: center; padding: 32px 16px; max-width: 420px; margin: 0 auto; }
.empty .ic { font-size: 24px; color: var(--fg-4); margin-bottom: 8px; }
.empty h4 { font-size: 16px; margin: 0 0 6px; }
.empty p { font-size: 14px; color: var(--fg-2); margin: 0 0 12px; }

/* spacing / radius / elevation / z */
.bars { display: grid; gap: 6px; }
.bar-row { display: grid; grid-template-columns: 66px 1fr; gap: 10px; align-items: center; font-family: var(--font-mono); font-size: 11px; color: var(--fg-3); }
.bar-row .b { height: 12px; background: color-mix(in oklab, var(--primary) 55%, transparent); border-radius: 2px; }
.rgrid { display: grid; grid-template-columns: repeat(5, minmax(0,1fr)); gap: 10px; }
.rbox { background: var(--raised); border: 1px solid var(--border); height: 64px; display: grid; place-items: center; font-family: var(--font-mono); font-size: 10px; color: var(--fg-3); }
.egrid { display: grid; gap: 10px; }
.elayer { padding: 12px 14px; border-radius: var(--radius-box); font-size: 12px; }
.e0 { background: var(--bg); border: 1px solid var(--border-subtle); }
.e1 { background: var(--raised); border: 1px solid var(--border-subtle); }
.e2 { background: var(--overlay); border: 1px solid var(--border); box-shadow: var(--shadow-overlay); }
.e3 { background: var(--overlay); border: 1px solid var(--border); box-shadow: var(--shadow-modal); }
.zrow { display: grid; grid-template-columns: 96px 44px 1fr; gap: 10px; align-items: center; font-size: 12px; padding: 4px 0; border-bottom: 1px solid var(--border-subtle); }
.zrow .t { font-family: var(--font-mono); color: var(--fg-3); }
.zrow .v { font-family: var(--font-mono); font-variant-numeric: tabular-nums; color: var(--primary-fg); text-align: right; }
.zbar { height: 8px; border-radius: 2px; background: color-mix(in oklab, var(--primary) 45%, transparent); }

/* layout diagrams */
.layout { display: flex; gap: 6px; height: 168px; }
.layout .box { border-radius: var(--radius-field); display: grid; place-items: center; font-family: var(--font-mono); font-size: 10px; color: var(--fg-3); border: 1px solid var(--border); background: var(--raised); text-align: center; padding: 4px; }
.layout .rail { flex: 0 0 64px; background: color-mix(in oklab, var(--primary) 10%, var(--raised)); }
.layout .col { flex: 1; }
.phone { width: 190px; border: 1px solid var(--border-strong); border-radius: 14px; overflow: hidden; display: grid; grid-template-rows: 40px 1fr 44px; height: 300px; }
.phone .top { display: grid; place-items: center; font-family: var(--font-mono); font-size: 10px; color: var(--fg-3); border-bottom: 1px solid var(--border-subtle); background: var(--raised); }
.phone .mid { background: var(--bg); display: grid; place-items: center; font-family: var(--font-mono); font-size: 10px; color: var(--fg-4); }
.phone .bot { display: grid; grid-template-columns: repeat(4,1fr); border-top: 1px solid var(--border-subtle); background: var(--raised); }
.phone .bot span { display: grid; place-items: center; font-family: var(--font-mono); font-size: 9px; color: var(--fg-3); }
.phone .bot span.on { color: var(--primary-fg); }

/* a11y list */
.a11y { display: grid; gap: 6px; }
.a11y .item { display: flex; gap: 10px; align-items: flex-start; padding: 8px 10px; border-radius: var(--radius-field); background: var(--raised); border: 1px solid var(--border-subtle); font-size: 13px; }
.a11y .item .st { flex: 0 0 auto; font-size: 11px; }
.kbd { display: inline-block; font-family: var(--font-mono); font-size: 11px; padding: 1px 5px; border-radius: 4px; background: color-mix(in oklab, var(--fg) 10%, transparent); border: 1px solid var(--border); color: var(--fg); }

/* footer */
footer { margin-top: 64px; padding: 24px 0 60px; border-top: 1px solid var(--border-subtle); font-size: 12px; color: var(--fg-3); }
footer .links { display: flex; flex-wrap: wrap; gap: 6px 16px; margin-bottom: 12px; }

/* ── 14. Responsive ────────────────────────────────────────────────────────── */
@media (max-width: 1100px) {
  .shell { grid-template-columns: 1fr; }
  .toc { position: static; max-height: none; overflow: visible; border-right: 0; border-bottom: 1px solid var(--border-subtle); display: flex; gap: 6px; overflow-x: auto; padding: 12px 16px; }
  .toc .label, .toc .grp { display: none; }
  .toc a { white-space: nowrap; border-left: 0; border-bottom: 2px solid transparent; }
  .toc a.active { border-left: 0; border-bottom-color: var(--primary); }
  main { padding: 0 16px 80px; }
  .g4, .g3 { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .rules, .pair, .state-grid { grid-template-columns: 1fr; }
  .ramp { grid-template-columns: repeat(5, minmax(0,1fr)); }
  .rgrid { grid-template-columns: repeat(3, minmax(0,1fr)); }
  th { position: static; }
}
@media (max-width: 640px) {
  .g2, .g3, .g4 { grid-template-columns: 1fr; }
  .cover h1 { font-size: 28px; line-height: 34px; }
  .spec { grid-template-columns: 1fr; gap: 2px; }
  .t-display { font-size: 30px; line-height: 34px; }
  .ramp { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .layout { flex-direction: column; height: auto; }
  .layout .rail { flex: 0 0 44px; }
  .layout .col { min-height: 52px; }
}

/* ── 15. Print ─────────────────────────────────────────────────────────────── */
@media print {
  html[data-theme] {
    --bg:#FFFFFF; --raised:#FAFAFC; --overlay:#F0F0F5; --sunken:#F3F4F6;
    --border-subtle:#EEEEF2; --border:#E2E2EA; --border-strong:#C9C9D4;
    --fg:#14141E; --fg-2:#3F3F52; --fg-3:#6B7280; --fg-4:#9CA3AF;
    --primary:#CC0099; --primary-fg:#CC0099;
  }
  .topbar, .toc, .copybtn, .iconbtn { display: none !important; }
  .shell { display: block; }
  main { padding: 0; max-width: none; }
  section { padding-top: 28px; break-inside: avoid; page-break-inside: avoid; }
  .cover { padding-top: 0; }
  a { border: 0; color: #CC0099; }
  .card, .demo, .do, .dont, .rule { break-inside: avoid; }
  figure.shot img { border-radius: 0; border: 1px solid var(--border); }
}

/* ── Resources & photographic assets ──────────────────────────────────────── */
figure.shot { margin: 0; display: grid; gap: 8px; }
figure.shot img { display: block; max-width: 100%; height: auto; border-radius: var(--radius-box); }
figure.shot figcaption { font-size: 12px; line-height: 1.5; color: var(--fg-3); }

/* Transparency mat: the checkerboard IS the alpha channel, not decoration. */
.mat { display: grid; place-items: center; padding: 20px; border-radius: var(--radius-box);
       border: 1px solid var(--border); }
.mat-check { background-color: #FFF;
  background-image:
    linear-gradient(45deg, #E7E7EF 25%, transparent 25%, transparent 75%, #E7E7EF 75%),
    linear-gradient(45deg, #E7E7EF 25%, transparent 25%, transparent 75%, #E7E7EF 75%);
  background-size: 16px 16px; background-position: 0 0, 8px 8px; }

/* One-colour rendering of the raster mark: the PNG alpha doubles as a mask.
   A rendering trick to show the variants — NOT an approved production method. */
.mark { display: inline-block; background: currentColor;
  -webkit-mask: url('../resources/logo.png') center / contain no-repeat;
  mask: url('../resources/logo.png') center / contain no-repeat; }
.mark-28 { width: 28px; height: 28px; }
</style>
